            assertThat(newStatus).isEqualTo("DRAFT");
            assertThat(thirdStatus).isEqualTo("PUBLISHED");
            assertThat(service.getRescheduleChain(oldKey).chain()).hasSize(1);
        }

        // 最终该区段 10:00-11:00 只有一张计划的时隙生效
