package com.example.starter.plan.model;

import java.time.LocalDate;

/**
 * 铁路走廊日计划主记录。
 *
 * @param id            主键
 * @param scheduleKey   计划业务键，全局唯一
 * @param opDate        运营日期（Asia/Shanghai 日历日）
 * @param version       版本号，草稿占用整体替换或编组变更成功一次加一
 * @param status        计划状态
 * @param consistLength 编组长度（辆，与站台有效长度同单位），未登记为 null
 */
public record DayPlan(long id, String scheduleKey, LocalDate opDate, int version, PlanStatus status,
                      Integer consistLength) {
}

package com.example.starter.plan.model;

/**
 * 站台主数据。
 *
 * @param code            站台代码，全局唯一
 * @param effectiveLength 站台有效长度（辆，与编组长度同单位），正整数
 */
public record Platform(String code, int effectiveLength) {
}

package com.example.starter.plan.model;

/**
 * 站台长度下调触发的编组超长风险快照。
 *
 * @param id             主键
 * @param planId         受影响计划 id
 * @param platformCode   被下调的站台代码
 * @param previousLength 固化快照：首次下调前站台有效长度（辆），后续再下调不改写
 * @param newLength      本次下调后的站台有效长度（辆）
 * @param consistLength  标记时刻计划编组长度快照（辆）
 * @param markedAt       风险标记时刻，UTC 毫秒
 * @param resolvedAt     风险解除时刻，UTC 毫秒；null 表示风险仍未解除
 */
public record PlatformRisk(long id, long planId, String platformCode, int previousLength,
                           int newLength, int consistLength, long markedAt, Long resolvedAt) {
}

package com.example.starter.plan.model;

import java.time.Instant;

/**
 * 已发布计划在某站台上的占用窗口（计划占用区段的最开始至最末结束，区间左闭右开）。
 *
 * @param scheduleKey   计划业务键
 * @param platformCode  站台代码
 * @param consistLength 编组长度（辆），未登记为 null
 * @param startUtc      占用开始时刻（含），UTC
 * @param endUtc        占用结束时刻（不含），UTC
 */
public record PlatformSpan(String scheduleKey, String platformCode, Integer consistLength,
                           Instant startUtc, Instant endUtc) {
}

