@Service
public class PlatformService {
    private final PlatformRepository platformRepo;
    private final IdempotencyRepository idemRepo;
    private final PlanRepository planRepo; // for acquirePublishLock
    private final ObjectMapper objectMapper;
    private final Clock businessClock;
    private final TransactionTemplate tx;

    public PlatformResponse createPlatform(PlatformCreateRequest req) {
        String code = req.code().trim();
        if (code.isEmpty()) throw badRequest; // @NotBlank on raw; trimmed empty e.g. " " passes @NotBlank? @NotBlank rejects whitespace-only. OK trim still.
        String hash = sha256("PLATFORM_CREATE\n" + req.operator() + "\n" + code + "\n" + req.effectiveLength());
        replay check...
        tx.execute: 
            if (platformRepo.findByCode(code).isPresent()) throw conflict PLATFORM_EXISTS
            insert; response; idem insert
