            .orElseThrow(() -> notFound(scheduleKey));
    return platformRepo.findRisksByPlan(plan.id()).stream()
            .map(r -> new PlatformRiskView(r.platformCode(), r.previousLength(), r.newLength(),
                    r.consistLength(), r.markedAt(), r.resolvedAt()))
            .toList();
}

