        // 风险快照查询：计划不存在 → 404
        mvc.perform(get("/api/v1/plans/{key}/platform-risk", key("SCH")))
                .andExpect(status().isNotFound());
    }

    // ---------- 辅助 ----------

    private void createPlatform(String code, int effectiveLength) throws Exception {
